database_schema.supabase_sql:
CREATE TABLE leads (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  name TEXT NOT NULL,
  email TEXT NOT NULL,
  source TEXT DEFAULT 'stylevault',
  created_at TIMESTAMPTZ DEFAULT now()
);

CREATE TABLE download_events (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  style_id TEXT NOT NULL,
  format TEXT NOT NULL CHECK (format IN ('json', 'css', 'tailwind')),
  palette_id TEXT,
  created_at TIMESTAMPTZ DEFAULT now()
);

CREATE TABLE extraction_events (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  email TEXT NOT NULL,
  identified_style TEXT,
  confidence NUMERIC,
  created_at TIMESTAMPTZ DEFAULT now()
);

ALTER TABLE leads ENABLE ROW LEVEL SECURITY;
ALTER TABLE download_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE extraction_events ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Allow anonymous inserts on leads"
  ON leads FOR INSERT WITH CHECK (true);
CREATE POLICY "Allow anonymous inserts on download_events"
  ON download_events FOR INSERT WITH CHECK (true);
CREATE POLICY "Allow anonymous inserts on extraction_events"
  ON extraction_events FOR INSERT WITH CHECK (true);
